def compute(vars):
    total_minimum_lease_payments = vars["v2"]
    payments_due_after_2015 = vars["v1"]

    if total_minimum_lease_payments == 0:
        return None

    ratio = payments_due_after_2015 / total_minimum_lease_payments
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "payments_due_after_2015": payments_due_after_2015,
            "total_minimum_lease_payments": total_minimum_lease_payments,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
